const ORIGINALS=[{"file":"src/bridge_request_tools.rs","sha256":"5ba0389968e32e9c99eebd7a38d32c80c8278e86278ace56290025c71a636941","source":"use serde_json::{Value, json};\n\npub fn system_text(system: &Value) -> Option<String> {\n    match system {\n        Value::String(text) if !text.is_empty() => Some(text.clone()),\n        Value::Array(blocks) => {\n            let text = blocks\n                .iter()\n                .filter_map(|block| block.get(\"text\").and_then(Value::as_str))\n                .collect::<Vec<_>>()\n                .join(\"\\n\\n\");\n            (!text.is_empty()).then_some(text)\n        }\n        _ => None,\n    }\n}\n\npub(super) fn translate_tools(tools: &[Value]) -> Vec<Value> {\n    tools\n        .iter()\n        .map(|tool| {\n            if tool\n                .get(\"type\")\n                .and_then(Value::as_str)\n                .is_some_and(|kind| kind.starts_with(\"web_search_\"))\n            {\n                return json!({\"type\": \"web_search\"});\n            }\n            if tool\n                .get(\"type\")\n                .and_then(Value::as_str)\n                .is_some_and(|kind| kind.starts_with(\"web_fetch_\"))\n            {\n                return json!({\"type\": \"web_fetch\"});\n            }\n            let mut mapped = json!({\n                \"type\": \"function\",\n                \"function\": {\n                    \"name\": tool.get(\"name\").and_then(Value::as_str).unwrap_or_default(),\n                    \"description\": tool.get(\"description\").cloned()\n                        .unwrap_or(Value::String(String::new())),\n                    \"parameters\": tool.get(\"input_schema\").cloned()\n                        .unwrap_or_else(|| json!({\"type\": \"object\", \"properties\": {}})),\n                }\n            });\n            if let Some(strict) = tool.get(\"strict\") {\n                mapped[\"function\"][\"strict\"] = strict.clone();\n            }\n            mapped\n        })\n        .collect()\n}\n\npub(super) fn translate_tool_choice(choice: &Value) -> Option<Value> {\n    match choice.get(\"type\").and_then(Value::as_str)? {\n        \"auto\" => Some(json!(\"auto\")),\n        \"any\" => Some(json!(\"required\")),\n        \"none\" => Some(json!(\"none\")),\n        \"tool\" => Some(json!({\n            \"type\": \"function\",\n            \"function\": {\"name\": choice.get(\"name\").and_then(Value::as_str)?},\n        })),\n        _ => None,\n    }\n}\n\npub(super) fn anthropic_effort(body: &Value) -> Result<Option<&'static str>, String> {\n    let effort = match body.get(\"output_config\") {\n        None | Some(Value::Null) => None,\n        Some(config) => {\n            let config = config\n                .as_object()\n                .ok_or_else(|| \"output_config must be an object\".to_string())?;\n            if let Some(field) = config\n                .keys()\n                .find(|field| !matches!(field.as_str(), \"effort\" | \"format\"))\n            {\n                return Err(format!(\"unsupported output_config field: {field}\"));\n            }\n            match config.get(\"effort\") {\n                None | Some(Value::Null) => None,\n                Some(effort) => {\n                    let effort = effort\n                        .as_str()\n                        .ok_or_else(|| \"output_config.effort must be a string\".to_string())?;\n                    Some(match effort {\n                        \"low\" => \"low\",\n                        \"medium\" => \"medium\",\n                        \"high\" => \"high\",\n                        \"max\" => \"xhigh\",\n                        _ => return Err(format!(\"unsupported output_config.effort: {effort}\")),\n                    })\n                }\n            }\n        }\n    };\n    if body.get(\"thinking\").is_some_and(|value| !value.is_null()) {\n        return crate::thinking::anthropic::translated_effort(body);\n    }\n    Ok(effort)\n}\n\npub(super) fn anthropic_response_format(body: &Value) -> Result<Option<Value>, String> {\n    let Some(format) = body\n        .get(\"output_config\")\n        .filter(|value| !value.is_null())\n        .and_then(|value| value.get(\"format\"))\n        .filter(|value| !value.is_null())\n    else {\n        return Ok(None);\n    };\n    let object = format\n        .as_object()\n        .ok_or_else(|| \"output_config.format must be an object\".to_string())?;\n    if let Some(field) = object\n        .keys()\n        .find(|field| !matches!(field.as_str(), \"type\" | \"schema\"))\n    {\n        return Err(format!(\"unsupported output_config.format field: {field}\"));\n    }\n    if object.get(\"type\").and_then(Value::as_str) != Some(\"json_schema\") {\n        return Err(\"output_config.format.type must be json_schema\".into());\n    }\n    let schema = object\n        .get(\"schema\")\n        .filter(|schema| schema.is_object())\n        .ok_or_else(|| \"output_config.format.schema must be an object\".to_string())?;\n    Ok(Some(json!({\n        \"type\": \"json_schema\",\n        \"json_schema\": {\n            \"name\": \"anthropic_output\",\n            \"strict\": true,\n            \"schema\": schema,\n        }\n    })))\n}\n\npub(super) fn anthropic_parallel_tool_calls(body: &Value) -> Result<Option<bool>, String> {\n    let Some(choice) = body.get(\"tool_choice\").filter(|value| !value.is_null()) else {\n        return Ok(None);\n    };\n    let Some(disable) = choice.get(\"disable_parallel_tool_use\") else {\n        return Ok(None);\n    };\n    disable\n        .as_bool()\n        .map(|disable| Some(!disable))\n        .ok_or_else(|| \"tool_choice.disable_parallel_tool_use must be a boolean\".into())\n}\n"},{"file":"src/gemini_bridge.rs","sha256":"cc8d02c94f8702946c064323d26df9bc4a845f9c84be6294f74497ccd2c183c5","source":"//! Native Gemini ↔ `OpenAI` Chat Completions translation.\n//!\n//! The Gemini CLI speaks only `generateContent`/`streamGenerateContent`. Its\n//! requests must therefore reach Codex, Claude and Qwen subscriptions through\n//! the router's `OpenAI` Chat Completions path, which every other namespace\n//! already shares. This module owns that translation in both directions so the\n//! HTTP handler in [`crate::gemini`] stays a thin router.\n//!\n//! The translation is intentionally lossless for the parts Gemini CLI actually\n//! uses: system instruction, multi-turn text, client function declarations,\n//! function calls, function results, generation config and usage metadata.\n\nuse serde_json::{Value, json};\n\n/// Gemini part-role for assistant turns.\nconst MODEL_ROLE: &str = \"model\";\n\n#[path = \"gemini_bridge_request.rs\"]\nmod request;\npub use request::{chat_to_gemini_request, gemini_request_to_chat};\npub(crate) use request::{\n    chat_to_gemini_request_checked, gemini_request_to_chat_checked, responses_to_chat_checked,\n};\n\n/// Translate an `OpenAI` Chat Completion into a native Gemini\n/// `GenerateContentResponse`.\n#[must_use]\npub fn chat_to_gemini_response(chat: &Value, model: &str) -> Value {\n    let choice = chat\n        .get(\"choices\")\n        .and_then(Value::as_array)\n        .and_then(|choices| choices.first());\n    let message = choice.and_then(|choice| choice.get(\"message\"));\n\n    let mut parts: Vec<Value> = Vec::new();\n    if let Some(text) = message\n        .and_then(|message| message.get(\"content\"))\n        .and_then(Value::as_str)\n        && !text.is_empty()\n    {\n        parts.push(json!({ \"text\": text }));\n    }\n    for call in message\n        .and_then(|message| message.get(\"tool_calls\"))\n        .and_then(Value::as_array)\n        .map_or(&[][..], Vec::as_slice)\n    {\n        let function = call.get(\"function\");\n        let name = function\n            .and_then(|function| function.get(\"name\"))\n            .and_then(Value::as_str)\n            .unwrap_or_default();\n        let args = function\n            .and_then(|function| function.get(\"arguments\"))\n            .and_then(Value::as_str)\n            .and_then(|arguments| serde_json::from_str::<Value>(arguments).ok())\n            .unwrap_or_else(|| json!({}));\n        let mut call_part = json!({ \"name\": name, \"args\": args });\n        if let Some(id) = call.get(\"id\").and_then(Value::as_str) {\n            call_part[\"id\"] = json!(id);\n        }\n        parts.push(json!({ \"functionCall\": call_part }));\n    }\n\n    let finish_reason = choice\n        .and_then(|choice| choice.get(\"finish_reason\"))\n        .and_then(Value::as_str)\n        .map_or(\"STOP\", map_finish_reason);\n\n    let usage = chat.get(\"usage\");\n    let prompt_tokens = usage\n        .and_then(|usage| usage.get(\"prompt_tokens\"))\n        .and_then(Value::as_u64)\n        .unwrap_or(0);\n    let completion_tokens = usage\n        .and_then(|usage| usage.get(\"completion_tokens\"))\n        .and_then(Value::as_u64)\n        .unwrap_or(0);\n\n    json!({\n        \"candidates\": [{\n            \"index\": 0,\n            \"content\": { \"role\": MODEL_ROLE, \"parts\": parts },\n            \"finishReason\": finish_reason,\n        }],\n        \"usageMetadata\": {\n            \"promptTokenCount\": prompt_tokens,\n            \"candidatesTokenCount\": completion_tokens,\n            \"totalTokenCount\": prompt_tokens + completion_tokens,\n        },\n        \"modelVersion\": model,\n    })\n}\n\nfn map_finish_reason(openai: &str) -> &'static str {\n    match openai {\n        \"length\" => \"MAX_TOKENS\",\n        \"content_filter\" => \"SAFETY\",\n        _ => \"STOP\",\n    }\n}\n\n/// Translate an `OpenAI`-shaped error body into Gemini's error envelope.\n#[must_use]\npub fn openai_error_to_gemini(status: u16, body: &Value) -> Value {\n    let message = body\n        .pointer(\"/error/message\")\n        .and_then(Value::as_str)\n        .unwrap_or(\"upstream request failed\");\n    let status_text = match status {\n        400 => \"INVALID_ARGUMENT\",\n        401 | 403 => \"PERMISSION_DENIED\",\n        404 => \"NOT_FOUND\",\n        429 => \"RESOURCE_EXHAUSTED\",\n        503 => \"UNAVAILABLE\",\n        _ => \"INTERNAL\",\n    };\n    json!({\n        \"error\": {\n            \"code\": status,\n            \"message\": message,\n            \"status\": status_text,\n        }\n    })\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn translates_system_instruction_and_multi_turn_text() {\n        let request = json!({\n            \"systemInstruction\": {\"parts\": [{\"text\": \"be terse\"}]},\n            \"contents\": [\n                {\"role\": \"user\", \"parts\": [{\"text\": \"hi\"}]},\n                {\"role\": \"model\", \"parts\": [{\"text\": \"hello\"}]},\n                {\"role\": \"user\", \"parts\": [{\"text\": \"more\"}]}\n            ],\n            \"generationConfig\": {\"maxOutputTokens\": 64, \"temperature\": 0.25}\n        });\n        let chat = gemini_request_to_chat(\"gpt-5.4-mini\", &request);\n        assert_eq!(chat[\"model\"], \"gpt-5.4-mini\");\n        let messages = chat[\"messages\"].as_array().unwrap();\n        assert_eq!(messages.len(), 4);\n        assert_eq!(messages[0][\"role\"], \"system\");\n        assert_eq!(messages[0][\"content\"], \"be terse\");\n        assert_eq!(messages[2][\"role\"], \"assistant\");\n        assert_eq!(chat[\"max_tokens\"], 64);\n        assert_eq!(chat[\"temperature\"], 0.25);\n    }\n\n    #[test]\n    fn translates_function_declarations_and_tool_mode() {\n        let request = json!({\n            \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": \"weather?\"}]}],\n            \"tools\": [{\"functionDeclarations\": [{\n                \"name\": \"get_weather\",\n                \"description\": \"look up weather\",\n                \"parameters\": {\"type\": \"object\", \"properties\": {\"city\": {\"type\": \"string\"}}}\n            }]}],\n            \"toolConfig\": {\"functionCallingConfig\": {\"mode\": \"ANY\"}}\n        });\n        let chat = gemini_request_to_chat(\"claude-opus-4-7\", &request);\n        let tools = chat[\"tools\"].as_array().unwrap();\n        assert_eq!(tools[0][\"function\"][\"name\"], \"get_weather\");\n        assert_eq!(tools[0][\"function\"][\"parameters\"][\"type\"], \"object\");\n        assert_eq!(tools.len(), 1);\n        assert_eq!(chat[\"tool_choice\"], \"required\");\n    }\n\n    #[test]\n    fn pairs_function_responses_with_the_call_they_answer() {\n        let request = json!({\n            \"contents\": [\n                {\"role\": \"user\", \"parts\": [{\"text\": \"weather?\"}]},\n                {\"role\": \"model\", \"parts\": [\n                    {\"functionCall\": {\"name\": \"get_weather\", \"args\": {\"city\": \"Lisbon\"}}}\n                ]},\n                {\"role\": \"user\", \"parts\": [\n                    {\"functionResponse\": {\"name\": \"get_weather\", \"response\": {\"c\": 21}}}\n                ]}\n            ]\n        });\n        let chat = gemini_request_to_chat(\"gpt-5.4-mini\", &request);\n        let messages = chat[\"messages\"].as_array().unwrap();\n        let call_id = messages[1][\"tool_calls\"][0][\"id\"].as_str().unwrap();\n        assert_eq!(\n            messages[1][\"tool_calls\"][0][\"function\"][\"arguments\"],\n            \"{\\\"city\\\":\\\"Lisbon\\\"}\"\n        );\n        assert_eq!(messages[2][\"role\"], \"tool\");\n        assert_eq!(messages[2][\"tool_call_id\"], call_id);\n    }\n\n    #[test]\n    fn honours_a_client_supplied_function_call_id() {\n        let request = json!({\n            \"contents\": [\n                {\"role\": \"model\", \"parts\": [\n                    {\"functionCall\": {\"id\": \"toolu_42\", \"name\": \"ls\", \"args\": {}}}\n                ]},\n                {\"role\": \"user\", \"parts\": [\n                    {\"functionResponse\": {\"name\": \"ls\", \"response\": {\"files\": []}}}\n                ]}\n            ]\n        });\n        let chat = gemini_request_to_chat(\"gpt-5.4-mini\", &request);\n        let messages = chat[\"messages\"].as_array().unwrap();\n        assert_eq!(messages[0][\"tool_calls\"][0][\"id\"], \"toolu_42\");\n        assert_eq!(messages[1][\"tool_call_id\"], \"toolu_42\");\n    }\n\n    #[test]\n    fn translates_chat_completion_text_and_usage() {\n        let chat = json!({\n            \"choices\": [{\n                \"index\": 0,\n                \"message\": {\"role\": \"assistant\", \"content\": \"answer\"},\n                \"finish_reason\": \"length\"\n            }],\n            \"usage\": {\"prompt_tokens\": 3, \"completion_tokens\": 5}\n        });\n        let gemini = chat_to_gemini_response(&chat, \"gpt-5.4-mini\");\n        assert_eq!(\n            gemini[\"candidates\"][0][\"content\"][\"parts\"][0][\"text\"],\n            \"answer\"\n        );\n        assert_eq!(gemini[\"candidates\"][0][\"content\"][\"role\"], \"model\");\n        assert_eq!(gemini[\"candidates\"][0][\"finishReason\"], \"MAX_TOKENS\");\n        assert_eq!(gemini[\"usageMetadata\"][\"totalTokenCount\"], 8);\n        assert_eq!(gemini[\"modelVersion\"], \"gpt-5.4-mini\");\n    }\n\n    #[test]\n    fn translates_chat_tool_calls_into_function_call_parts() {\n        let chat = json!({\n            \"choices\": [{\n                \"message\": {\n                    \"role\": \"assistant\",\n                    \"content\": \"\",\n                    \"tool_calls\": [{\n                        \"id\": \"call_1\",\n                        \"type\": \"function\",\n                        \"function\": {\"name\": \"get_weather\", \"arguments\": \"{\\\"city\\\":\\\"Lisbon\\\"}\"}\n                    }]\n                },\n                \"finish_reason\": \"tool_calls\"\n            }]\n        });\n        let gemini = chat_to_gemini_response(&chat, \"claude-opus-4-7\");\n        let part = &gemini[\"candidates\"][0][\"content\"][\"parts\"][0][\"functionCall\"];\n        assert_eq!(part[\"name\"], \"get_weather\");\n        assert_eq!(part[\"args\"][\"city\"], \"Lisbon\");\n        assert_eq!(part[\"id\"], \"call_1\");\n        assert_eq!(gemini[\"candidates\"][0][\"finishReason\"], \"STOP\");\n    }\n\n    #[test]\n    fn maps_openai_errors_onto_the_gemini_envelope() {\n        let error = openai_error_to_gemini(\n            429,\n            &json!({\"error\": {\"message\": \"slow down\", \"type\": \"rate_limit_error\"}}),\n        );\n        assert_eq!(error[\"error\"][\"code\"], 429);\n        assert_eq!(error[\"error\"][\"message\"], \"slow down\");\n        assert_eq!(error[\"error\"][\"status\"], \"RESOURCE_EXHAUSTED\");\n    }\n}\n"},{"file":"src/openai_tools.rs","sha256":"be8257493ce589b6442c1d6e107cee4111011900f7cca9db5a747b949d7e629f","source":"use serde_json::{Value, json};\n\nuse super::ChatMessage;\n\npub fn extract_text(content: &Value) -> Option<String> {\n    match content {\n        Value::String(s) => Some(s.clone()),\n        Value::Array(parts) => {\n            let mut buf = String::new();\n            for p in parts {\n                if let Some(t) = p.get(\"text\").and_then(Value::as_str) {\n                    buf.push_str(t);\n                } else if let Some(s) = p.as_str() {\n                    buf.push_str(s);\n                }\n            }\n            if buf.is_empty() { None } else { Some(buf) }\n        }\n        _ => None,\n    }\n}\n\npub fn translate_parts(parts: &[Value]) -> Vec<Value> {\n    parts\n        .iter()\n        .filter_map(|p| {\n            let kind = p.get(\"type\").and_then(Value::as_str).unwrap_or(\"text\");\n            match kind {\n                \"text\" | \"input_text\" | \"output_text\" => {\n                    let text = p.get(\"text\").and_then(Value::as_str).unwrap_or(\"\");\n                    let mut block = json!({\"type\": \"text\", \"text\": text});\n                    if p.get(\"prompt_cache_breakpoint\").is_some() {\n                        block[\"cache_control\"] = json!({\"type\": \"ephemeral\"});\n                    }\n                    Some(block)\n                }\n                \"image_url\" => {\n                    let url = p\n                        .get(\"image_url\")\n                        .and_then(|v| v.get(\"url\"))\n                        .and_then(Value::as_str)\n                        .unwrap_or(\"\");\n                    let mut block = json!({\n                        \"type\": \"image\",\n                        \"source\": {\"type\": \"url\", \"url\": url}\n                    });\n                    if p.get(\"prompt_cache_breakpoint\").is_some() {\n                        block[\"cache_control\"] = json!({\"type\": \"ephemeral\"});\n                    }\n                    Some(block)\n                }\n                \"input_image\" => {\n                    let url = p.get(\"image_url\").and_then(Value::as_str).unwrap_or(\"\");\n                    let mut block = json!({\n                        \"type\": \"image\",\n                        \"source\": {\"type\": \"url\", \"url\": url}\n                    });\n                    if p.get(\"prompt_cache_breakpoint\").is_some() {\n                        block[\"cache_control\"] = json!({\"type\": \"ephemeral\"});\n                    }\n                    Some(block)\n                }\n                _ => None,\n            }\n        })\n        .collect()\n}\n\n/// Whether a tool entry can be represented in the Anthropic dialect.\n///\n/// Anthropic understands function tools and the two server-side tools. Codex\n/// CLI additionally sends `namespace`, `custom` and `tool_search` as part of its\n/// ordinary tool set, and those have no Anthropic equivalent.\nfn is_translatable(tool: &Value) -> bool {\n    let kind = tool\n        .get(\"type\")\n        .and_then(Value::as_str)\n        .unwrap_or(\"function\");\n    match kind {\n        \"function\" => tool\n            .get(\"function\")\n            .unwrap_or(tool)\n            .get(\"name\")\n            .and_then(Value::as_str)\n            .is_some_and(|name| !name.is_empty()),\n        \"web_search\" | \"web_fetch\" => true,\n        _ => false,\n    }\n}\n\n/// A human-readable name for a tool entry, for reporting what was dropped.\nfn tool_label(tool: &Value) -> String {\n    let kind = tool\n        .get(\"type\")\n        .and_then(Value::as_str)\n        .unwrap_or(\"function\");\n    tool.get(\"function\")\n        .unwrap_or(tool)\n        .get(\"name\")\n        .and_then(Value::as_str)\n        .filter(|name| !name.is_empty())\n        .map_or_else(|| kind.to_string(), |name| format!(\"{kind} ({name})\"))\n}\n\n/// Tool entries that cannot cross into the Anthropic dialect, in order.\n///\n/// Dropping these is preferable to refusing the request. A model is never\n/// obliged to call a tool, so a request carrying the nine usable tools of a\n/// Codex turn is far more useful than a `400` naming the one that did not fit\n/// (issue #215). The caller is told what was dropped rather than left to infer\n/// it from an agent that quietly never uses sub-agents.\n#[must_use]\npub fn untranslatable_anthropic_tools(tools: &Value) -> Vec<String> {\n    tools.as_array().map_or_else(Vec::new, |tools| {\n        tools\n            .iter()\n            .filter(|tool| !is_translatable(tool))\n            .map(tool_label)\n            .collect()\n    })\n}\n\npub fn translate_tools(tools: &Value) -> Value {\n    match tools {\n        Value::Array(arr) => {\n            let mapped: Vec<Value> = arr\n                .iter()\n                // An untranslatable entry is dropped rather than passed through\n                // verbatim: forwarding a shape Anthropic does not define would\n                // trade a router `400` for a vendor one (issue #215).\n                .filter(|t| is_translatable(t))\n                .map(|t| {\n                    let kind = t.get(\"type\").and_then(Value::as_str).unwrap_or(\"function\");\n                    match kind {\n                        \"web_search\" => {\n                            let mut tool = json!({\n                                \"type\": \"web_search_20250305\",\n                                \"name\": \"web_search\",\n                            });\n                            for key in [\n                                \"max_uses\",\n                                \"allowed_domains\",\n                                \"blocked_domains\",\n                                \"user_location\",\n                            ] {\n                                if let Some(value) = t.get(key) {\n                                    tool[key] = value.clone();\n                                }\n                            }\n                            return tool;\n                        }\n                        \"web_fetch\" => {\n                            let mut tool = json!({\n                                \"type\": \"web_fetch_20250910\",\n                                \"name\": \"web_fetch\",\n                            });\n                            if let Some(max_uses) = t.get(\"max_uses\") {\n                                tool[\"max_uses\"] = max_uses.clone();\n                            }\n                            return tool;\n                        }\n                        \"function\" => {}\n                        _ => return t.clone(),\n                    }\n                    // Chat Completions nests a function definition while the\n                    // Responses API keeps the same fields flat.\n                    let func = t.get(\"function\").unwrap_or(t);\n                    let name = func\n                        .get(\"name\")\n                        .and_then(Value::as_str)\n                        .unwrap_or_default()\n                        .to_string();\n                    let description = func\n                        .get(\"description\")\n                        .cloned()\n                        .unwrap_or(Value::String(String::new()));\n                    let parameters = func.get(\"parameters\").cloned().unwrap_or_else(|| json!({}));\n                    let mut mapped = json!({\n                        \"name\": name,\n                        \"description\": description,\n                        \"input_schema\": parameters,\n                    });\n                    if let Some(strict) = func.get(\"strict\") {\n                        mapped[\"strict\"] = strict.clone();\n                    }\n                    mapped\n                })\n                .collect();\n            Value::Array(mapped)\n        }\n        other => other.clone(),\n    }\n}\n\n/// Validate function-tool fields that must survive an Anthropic bridge.\n#[must_use]\npub fn invalid_anthropic_tool_definition(tools: &Value) -> Option<String> {\n    let Some(tools) = tools.as_array() else {\n        return Some(\"tools must be an array\".into());\n    };\n    for (index, tool) in tools.iter().enumerate() {\n        let kind = tool\n            .get(\"type\")\n            .and_then(Value::as_str)\n            .unwrap_or(\"function\");\n        if kind != \"function\" {\n            continue;\n        }\n        let function = tool.get(\"function\").unwrap_or(tool);\n        if function\n            .get(\"name\")\n            .and_then(Value::as_str)\n            .is_none_or(str::is_empty)\n        {\n            return Some(format!(\"tools[{index}] is missing function name\"));\n        }\n        if function\n            .get(\"parameters\")\n            .is_some_and(|schema| !schema.is_object())\n        {\n            return Some(format!(\"tools[{index}].parameters must be an object\"));\n        }\n        if function\n            .get(\"strict\")\n            .is_some_and(|strict| !strict.is_boolean())\n        {\n            return Some(format!(\"tools[{index}].strict must be a boolean\"));\n        }\n    }\n    None\n}\n\n/// Validate prior Chat tool turns before translating them to Anthropic. Empty\n/// identifiers or malformed JSON arguments cannot be repaired without losing\n/// the caller's tool protocol state.\n#[must_use]\npub fn untranslatable_chat_tool_history(messages: &[ChatMessage]) -> Option<String> {\n    for message in messages {\n        if message.content.as_array().is_some_and(|parts| {\n            parts\n                .iter()\n                .any(|part| part.get(\"type\").and_then(Value::as_str) == Some(\"input_audio\"))\n        }) {\n            return Some(\n                \"input_audio content cannot be represented by the selected Anthropic provider\"\n                    .into(),\n            );\n        }\n        if message.role == \"tool\" && message.tool_call_id.as_deref().is_none_or(str::is_empty) {\n            return Some(\"role=tool message is missing tool_call_id\".into());\n        }\n        let Some(tool_calls) = message.tool_calls.as_ref() else {\n            continue;\n        };\n        let Some(tool_calls) = tool_calls.as_array() else {\n            return Some(\"assistant tool_calls must be an array\".into());\n        };\n        for call in tool_calls {\n            if call\n                .get(\"id\")\n                .and_then(Value::as_str)\n                .is_none_or(str::is_empty)\n            {\n                return Some(\"assistant tool call is missing id\".into());\n            }\n            let Some(function) = call.get(\"function\") else {\n                return Some(\"assistant tool call is missing function\".into());\n            };\n            if function\n                .get(\"name\")\n                .and_then(Value::as_str)\n                .is_none_or(str::is_empty)\n            {\n                return Some(\"assistant tool call is missing function.name\".into());\n            }\n            let Some(arguments) = function.get(\"arguments\").and_then(Value::as_str) else {\n                return Some(\"assistant tool call is missing string function.arguments\".into());\n            };\n            if serde_json::from_str::<Value>(arguments).is_err() {\n                return Some(\"assistant tool call function.arguments is not valid JSON\".into());\n            }\n        }\n    }\n    None\n}\n\npub fn translate_tool_choice(choice: &Value) -> Value {\n    match choice {\n        Value::String(s) => match s.as_str() {\n            \"required\" => json!({\"type\": \"any\"}),\n            \"none\" => json!({\"type\": \"none\"}),\n            // \"auto\" plus any unrecognised string default to auto.\n            _ => json!({\"type\": \"auto\"}),\n        },\n        Value::Object(map) => {\n            if let Some(func) = map.get(\"function\").and_then(Value::as_object)\n                && let Some(name) = func.get(\"name\").and_then(Value::as_str)\n            {\n                return json!({\"type\": \"tool\", \"name\": name});\n            }\n            if map.get(\"type\").and_then(Value::as_str) == Some(\"function\")\n                && let Some(name) = map.get(\"name\").and_then(Value::as_str)\n            {\n                return json!({\"type\": \"tool\", \"name\": name});\n            }\n            json!({\"type\": \"auto\"})\n        }\n        _ => json!({\"type\": \"auto\"}),\n    }\n}\n\n/// Return a semantic error for a tool-choice shape that would otherwise be\n/// silently weakened to `auto` during Anthropic translation.\n#[must_use]\npub fn untranslatable_anthropic_tool_choice(choice: &Value) -> Option<String> {\n    match choice {\n        Value::String(mode) if matches!(mode.as_str(), \"auto\" | \"required\" | \"none\") => None,\n        Value::Object(map) => {\n            let nested_name = map\n                .get(\"function\")\n                .and_then(Value::as_object)\n                .and_then(|function| function.get(\"name\"))\n                .and_then(Value::as_str);\n            let flat_name = (map.get(\"type\").and_then(Value::as_str) == Some(\"function\"))\n                .then(|| map.get(\"name\").and_then(Value::as_str))\n                .flatten();\n            (nested_name.is_none() && flat_name.is_none())\n                .then(|| \"tool_choice must select auto, required, none, or a named function\".into())\n        }\n        _ => Some(\"tool_choice must select auto, required, none, or a named function\".into()),\n    }\n}\n"},{"file":"src/bridge_response.rs","sha256":"5dc06a1b9326f20e357391fc3aae75ef06ec8c151835b4b257011c3cf0136340","source":"//! Shared semantics for Anthropic responses translated to `OpenAI` surfaces.\n\nuse serde_json::{Value, json};\n\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub struct StopSemantics {\n    pub chat_finish_reason: &'static str,\n    pub response_status: &'static str,\n    pub incomplete_reason: Option<&'static str>,\n    pub refusal: bool,\n}\n\n#[must_use]\npub fn stop_semantics(reason: Option<&str>) -> StopSemantics {\n    match reason.unwrap_or(\"end_turn\") {\n        \"end_turn\" | \"stop_sequence\" => complete(\"stop\"),\n        \"tool_use\" => complete(\"tool_calls\"),\n        \"refusal\" => incomplete(\"content_filter\", \"content_filter\", true),\n        \"max_tokens\" | \"pause_turn\" | \"model_context_window_exceeded\" => {\n            incomplete(\"length\", \"max_output_tokens\", false)\n        }\n        _ => incomplete(\"length\", \"max_output_tokens\", false),\n    }\n}\n\nconst fn complete(chat_finish_reason: &'static str) -> StopSemantics {\n    StopSemantics {\n        chat_finish_reason,\n        response_status: \"completed\",\n        incomplete_reason: None,\n        refusal: false,\n    }\n}\n\nconst fn incomplete(\n    chat_finish_reason: &'static str,\n    reason: &'static str,\n    refusal: bool,\n) -> StopSemantics {\n    StopSemantics {\n        chat_finish_reason,\n        response_status: \"incomplete\",\n        incomplete_reason: Some(reason),\n        refusal,\n    }\n}\n\n#[derive(Clone, Debug, Default, Eq, PartialEq)]\npub struct AnthropicUsage {\n    input_tokens: u64,\n    cache_creation_input_tokens: u64,\n    cache_read_input_tokens: u64,\n    output_tokens: u64,\n    service_tier: Option<String>,\n    server_tool_use: Option<Value>,\n}\n\nimpl AnthropicUsage {\n    pub fn absorb(&mut self, usage: Option<&Value>) {\n        let Some(usage) = usage else {\n            return;\n        };\n        update(&mut self.input_tokens, usage, \"input_tokens\");\n        update(\n            &mut self.cache_creation_input_tokens,\n            usage,\n            \"cache_creation_input_tokens\",\n        );\n        update(\n            &mut self.cache_read_input_tokens,\n            usage,\n            \"cache_read_input_tokens\",\n        );\n        update(&mut self.output_tokens, usage, \"output_tokens\");\n        if let Some(tier) = usage.get(\"service_tier\").and_then(Value::as_str) {\n            self.service_tier = Some(tier.to_string());\n        }\n        if let Some(server_tool_use) = usage.get(\"server_tool_use\") {\n            self.server_tool_use = Some(server_tool_use.clone());\n        }\n    }\n\n    #[must_use]\n    pub fn from_value(usage: Option<&Value>) -> Self {\n        let mut mapped = Self::default();\n        mapped.absorb(usage);\n        mapped\n    }\n\n    #[must_use]\n    pub const fn total_input(&self) -> u64 {\n        self.input_tokens\n            .saturating_add(self.cache_creation_input_tokens)\n            .saturating_add(self.cache_read_input_tokens)\n    }\n\n    #[must_use]\n    pub fn chat(&self) -> Value {\n        let input = self.total_input();\n        json!({\n            \"prompt_tokens\": input,\n            \"completion_tokens\": self.output_tokens,\n            \"total_tokens\": input.saturating_add(self.output_tokens),\n            \"prompt_tokens_details\": {\"cached_tokens\": self.cache_read_input_tokens},\n        })\n    }\n\n    #[must_use]\n    pub fn responses(&self) -> Value {\n        let input = self.total_input();\n        let mut usage = json!({\n            \"input_tokens\": input,\n            \"input_tokens_details\": {\"cached_tokens\": self.cache_read_input_tokens},\n            \"output_tokens\": self.output_tokens,\n            \"output_tokens_details\": {\"reasoning_tokens\": 0},\n            \"total_tokens\": input.saturating_add(self.output_tokens),\n        });\n        if let Some(server_tool_use) = &self.server_tool_use {\n            usage[\"server_tool_use\"] = server_tool_use.clone();\n        }\n        usage\n    }\n\n    #[must_use]\n    pub fn openai_service_tier(&self) -> Option<&'static str> {\n        match self.service_tier.as_deref() {\n            Some(\"standard\") => Some(\"default\"),\n            Some(\"priority\") => Some(\"priority\"),\n            _ => None,\n        }\n    }\n}\n\n/// Map `OpenAI` usage back to Anthropic without double-counting cache hits.\n#[must_use]\npub fn openai_usage_to_anthropic(usage: Option<&Value>) -> Value {\n    let input_total = usage\n        .and_then(|value| {\n            value\n                .get(\"input_tokens\")\n                .or_else(|| value.get(\"prompt_tokens\"))\n        })\n        .and_then(Value::as_u64)\n        .unwrap_or(0);\n    let output = usage\n        .and_then(|value| {\n            value\n                .get(\"output_tokens\")\n                .or_else(|| value.get(\"completion_tokens\"))\n        })\n        .and_then(Value::as_u64)\n        .unwrap_or(0);\n    let cached = usage\n        .and_then(|value| {\n            value\n                .pointer(\"/input_tokens_details/cached_tokens\")\n                .or_else(|| value.pointer(\"/prompt_tokens_details/cached_tokens\"))\n        })\n        .and_then(Value::as_u64)\n        .unwrap_or(0)\n        .min(input_total);\n    json!({\n        \"input_tokens\": input_total.saturating_sub(cached),\n        \"cache_creation_input_tokens\": 0,\n        \"cache_read_input_tokens\": cached,\n        \"output_tokens\": output,\n    })\n}\n\n#[must_use]\npub fn anthropic_service_tier_from_openai(value: Option<&Value>) -> Option<&'static str> {\n    match value.and_then(Value::as_str) {\n        Some(\"default\" | \"auto\") => Some(\"standard\"),\n        Some(\"priority\") => Some(\"priority\"),\n        _ => None,\n    }\n}\n\nfn update(slot: &mut u64, usage: &Value, key: &str) {\n    if let Some(value) = usage.get(key).and_then(Value::as_u64) {\n        *slot = value;\n    }\n}\n\n/// Concatenate Anthropic text blocks and build flat `OpenAI` URL annotations.\n#[must_use]\npub fn anthropic_text_and_annotations(content: Option<&Value>) -> (String, Vec<Value>) {\n    let mut text = String::new();\n    let mut annotations = Vec::new();\n    for block in content\n        .and_then(Value::as_array)\n        .map(Vec::as_slice)\n        .unwrap_or_default()\n    {\n        if block.get(\"type\").and_then(Value::as_str) != Some(\"text\") {\n            continue;\n        }\n        let block_text = block\n            .get(\"text\")\n            .and_then(Value::as_str)\n            .unwrap_or_default();\n        let base = text.chars().count() as u64;\n        let mut search_from = 0_usize;\n        for citation in block\n            .get(\"citations\")\n            .and_then(Value::as_array)\n            .map(Vec::as_slice)\n            .unwrap_or_default()\n        {\n            let Some(url) = citation_url(citation) else {\n                continue;\n            };\n            let Some(cited) = citation.get(\"cited_text\").and_then(Value::as_str) else {\n                continue;\n            };\n            let Some((start, end, next)) = find_char_range(block_text, cited, search_from) else {\n                continue;\n            };\n            search_from = next;\n            annotations.push(json!({\n                \"type\": \"url_citation\",\n                \"url\": url,\n                \"title\": citation.get(\"title\").cloned().unwrap_or(Value::Null),\n                \"start_index\": base.saturating_add(start),\n                \"end_index\": base.saturating_add(end),\n            }));\n        }\n        text.push_str(block_text);\n    }\n    (text, annotations)\n}\n\nfn citation_url(citation: &Value) -> Option<&str> {\n    match citation.get(\"type\").and_then(Value::as_str) {\n        Some(\"web_search_result_location\") => citation.get(\"url\").and_then(Value::as_str),\n        Some(\"search_result_location\") => citation\n            .get(\"source\")\n            .and_then(Value::as_str)\n            .filter(|source| source.starts_with(\"https://\") || source.starts_with(\"http://\")),\n        _ => None,\n    }\n}\n\nfn find_char_range(text: &str, cited: &str, from: usize) -> Option<(u64, u64, usize)> {\n    let relative = text.get(from..)?.find(cited)?;\n    let start_byte = from + relative;\n    let end_byte = start_byte + cited.len();\n    let start = text.get(..start_byte)?.chars().count() as u64;\n    let end = text.get(..end_byte)?.chars().count() as u64;\n    Some((start, end, end_byte))\n}\n\n#[must_use]\npub fn chat_annotations(flat: &[Value]) -> Vec<Value> {\n    flat.iter()\n        .map(|annotation| {\n            json!({\n                \"type\": \"url_citation\",\n                \"url_citation\": {\n                    \"url\": annotation.get(\"url\").cloned().unwrap_or(Value::Null),\n                    \"title\": annotation.get(\"title\").cloned().unwrap_or(Value::Null),\n                    \"start_index\": annotation.get(\"start_index\").cloned().unwrap_or(Value::Null),\n                    \"end_index\": annotation.get(\"end_index\").cloned().unwrap_or(Value::Null),\n                }\n            })\n        })\n        .collect()\n}\n\n#[must_use]\npub fn annotation_from_anthropic_delta(\n    delta: &Value,\n    text: &str,\n    from: usize,\n) -> Option<(Value, usize)> {\n    let citation = delta.get(\"citation\")?;\n    let url = citation_url(citation)?;\n    let cited = citation.get(\"cited_text\").and_then(Value::as_str)?;\n    let (start, end, next) = find_char_range(text, cited, from)?;\n    Some((\n        json!({\n            \"type\": \"url_citation\",\n            \"url\": url,\n            \"title\": citation.get(\"title\").cloned().unwrap_or(Value::Null),\n            \"start_index\": start,\n            \"end_index\": end,\n        }),\n        next,\n    ))\n}\n\n/// Convert URL/document annotations to Anthropic citations without changing\n/// their order or Unicode character offsets.\npub fn openai_annotations_to_anthropic(\n    text: &str,\n    annotations: Option<&Value>,\n    chat_shape: bool,\n) -> Result<Vec<Value>, String> {\n    let Some(annotations) = annotations else {\n        return Ok(Vec::new());\n    };\n    let annotations = annotations\n        .as_array()\n        .ok_or_else(|| \"annotations must be an array\".to_string())?;\n    annotations\n        .iter()\n        .enumerate()\n        .map(|(index, wrapper)| {\n            let annotation = if chat_shape {\n                wrapper.get(\"url_citation\").unwrap_or(wrapper)\n            } else {\n                wrapper\n            };\n            let kind = annotation\n                .get(\"type\")\n                .and_then(Value::as_str)\n                .or_else(|| wrapper.get(\"type\").and_then(Value::as_str))\n                .unwrap_or(\"url_citation\");\n            let start = annotation\n                .get(\"start_index\")\n                .and_then(Value::as_u64)\n                .ok_or_else(|| format!(\"annotations[{index}].start_index is required\"))?;\n            let end = annotation\n                .get(\"end_index\")\n                .and_then(Value::as_u64)\n                .ok_or_else(|| format!(\"annotations[{index}].end_index is required\"))?;\n            let cited_text = char_slice(text, start, end)\n                .ok_or_else(|| format!(\"annotations[{index}] has invalid text offsets\"))?;\n            match kind {\n                \"url_citation\" => Ok(json!({\n                    \"type\": \"web_search_result_location\",\n                    \"url\": required_annotation_string(annotation, \"url\", index)?,\n                    \"title\": required_annotation_string(annotation, \"title\", index)?,\n                    \"cited_text\": cited_text,\n                })),\n                \"file_citation\" => Ok(json!({\n                    \"type\": \"char_location\",\n                    \"document_index\": annotation.get(\"document_index\").and_then(Value::as_u64)\n                        .ok_or_else(|| format!(\"annotations[{index}].document_index is required\"))?,\n                    \"document_title\": annotation.get(\"filename\").or_else(|| annotation.get(\"title\"))\n                        .and_then(Value::as_str)\n                        .ok_or_else(|| format!(\"annotations[{index}].filename is required\"))?,\n                    \"start_char_index\": start,\n                    \"end_char_index\": end,\n                    \"cited_text\": cited_text,\n                })),\n                _ => Err(format!(\n                    \"annotations[{index}] type {kind} cannot be represented by Anthropic\"\n                )),\n            }\n        })\n        .collect()\n}\n\nfn required_annotation_string<'a>(\n    annotation: &'a Value,\n    field: &str,\n    index: usize,\n) -> Result<&'a str, String> {\n    annotation\n        .get(field)\n        .and_then(Value::as_str)\n        .filter(|value| !value.is_empty())\n        .ok_or_else(|| format!(\"annotations[{index}].{field} is required\"))\n}\n\nfn char_slice(text: &str, start: u64, end: u64) -> Option<String> {\n    if end < start {\n        return None;\n    }\n    let start = usize::try_from(start).ok()?;\n    let end = usize::try_from(end).ok()?;\n    Some(text.chars().skip(start).take(end - start).collect())\n        .filter(|slice: &String| slice.chars().count() == end - start)\n}\n\n/// Validate every annotation in a successful upstream `OpenAI` response.\npub fn validate_openai_response_citations(payload: &Value) -> Result<(), String> {\n    if let Some(message) = payload.pointer(\"/choices/0/message\")\n        && let Some(text) = message.get(\"content\").and_then(Value::as_str)\n    {\n        openai_annotations_to_anthropic(text, message.get(\"annotations\"), true)?;\n    }\n    for item in payload\n        .get(\"output\")\n        .and_then(Value::as_array)\n        .into_iter()\n        .flatten()\n    {\n        for part in item\n            .get(\"content\")\n            .and_then(Value::as_array)\n            .into_iter()\n            .flatten()\n        {\n            if let Some(text) = part.get(\"text\").and_then(Value::as_str) {\n                openai_annotations_to_anthropic(text, part.get(\"annotations\"), false)?;\n            }\n        }\n    }\n    Ok(())\n}\n\npub fn validate_anthropic_response_citations(content: Option<&Value>) -> Result<(), String> {\n    for (block_index, block) in content\n        .and_then(Value::as_array)\n        .into_iter()\n        .flatten()\n        .enumerate()\n    {\n        let Some(citations) = block.get(\"citations\") else {\n            continue;\n        };\n        let citations = citations\n            .as_array()\n            .ok_or_else(|| format!(\"content[{block_index}].citations must be an array\"))?;\n        let text = block\n            .get(\"text\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| format!(\"content[{block_index}].text is required\"))?;\n        let mut from = 0;\n        for (citation_index, citation) in citations.iter().enumerate() {\n            citation_url(citation).ok_or_else(|| {\n                format!(\"content[{block_index}].citations[{citation_index}] is not a compatible URL citation\")\n            })?;\n            let cited = citation\n                .get(\"cited_text\")\n                .and_then(Value::as_str)\n                .filter(|value| !value.is_empty())\n                .ok_or_else(|| {\n                    format!(\n                        \"content[{block_index}].citations[{citation_index}].cited_text is required\"\n                    )\n                })?;\n            let (_, _, next) = find_char_range(text, cited, from).ok_or_else(|| {\n                format!(\"content[{block_index}].citations[{citation_index}] does not match its text block\")\n            })?;\n            from = next;\n        }\n    }\n    Ok(())\n}\n"}];
